export type CheckoutPurpose =
  | {
      kind: "order";
      userId: string;
      intent: OrderIntent;
      sold: OrderPrice | null;
      campaign: string;
      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
      promoReservationToken: string | null;
      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
      couponReservationToken: string | null;
    }
  | {
      kind: "gameOrder";
      userId: string;
      intent: GameOrderIntent;
      /** The price the game order was SOLD at; null only on a malformed stamp. */
      sold: GameOrderPrice | null;
      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
      couponReservationToken: string | null;
    }
  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
  /** A dedicated-IP add-on purchased for an already-provisioned server (VPS or
   *  game). `chargeCents` is the FULL proration to debit on confirm, same
   *  convention as `resize`/`diskExpand`. */
  | { kind: "dedicatedIp"; userId: string; serverId: string; chargeCents: number }
  /** A shared-hosting order funded by card: the wallet was topped by the card leg,
   *  and `intent` is what `placeHostingOrder` re-places (debiting the wallet). */
  | { kind: "hostOrder"; userId: string; intent: HostOrderCheckoutIntent }
  /** A business-email order funded by card — the email analogue of `hostOrder`. */
  | { kind: "emailOrder"; userId: string; intent: EmailOrderCheckoutIntent }
  /** A domain registration funded by card. `domainOrderId` points at the
   *  `DomainOrderIntent` row `placeDomainCardOrder` reads for the actual
   *  registrant contact + price; `sold` is a metadata-only mirror of that row's
   *  price, present so a malformed/missing price never turns this into
   *  `unreadable` (the row, not the metadata, is what fulfilment charges). */
  | { kind: "domainOrder"; userId: string; domainOrderId: string; sold: DomainOrderPrice | null }
  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
  | { kind: "topup"; userId: string | null }
  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
  | { kind: "unpaid" }
  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
  | { kind: "unreadable"; userId: string | null; detail: string };

/**
 * Classify a retrieved session. Pure — no clock, no network, no database — so the
 * routing decision is unit-testable and identical for the redirect and the webhook.
 */
export function classifyCheckoutSession(
  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
): CheckoutPurpose {
  const md = session.metadata ?? null;
  const userId = parseId(md?.nxeonUserId);
  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };

  const orderRaw = md?.nxeonOrder;
  if (orderRaw) {
    let intent: unknown;
    try {
      intent = JSON.parse(orderRaw);
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
    }
    if (!intent || typeof intent !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
    }
    return {
      kind: "order",
      userId,
      intent: intent as OrderIntent,
      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
      promoReservationToken: parseId(md?.nxeonPromoReservation),
      couponReservationToken: parseId(md?.nxeonCouponReservation),
    };
  }

  const gameRaw = md?.nxeonGameOrder;
  if (gameRaw) {
    let slim: Record<string, unknown>;
    try {
      slim = JSON.parse(gameRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not valid JSON" };
    }
    if (!slim || typeof slim !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not an object" };
    }
    const gamePlanId = parseId(slim.gamePlanId);
    if (!gamePlanId) {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is missing gamePlanId" };
    }
    // The gameplay config rides in its own optional key; a missing/garbled blob is
    // simply dropped (placeGameOrder fills defaults), never treated as unreadable —
    // it is not money and cannot change the settled charge.
    let config: Record<string, unknown> | null = null;
    const rawCfg = md?.nxeonGameConfig;
    if (typeof rawCfg === "string" && rawCfg !== "") {
      try {
        const p = JSON.parse(rawCfg);
        if (p && typeof p === "object") config = p as Record<string, unknown>;
      } catch {
        config = null;
      }
    }
    const intent: GameOrderIntent = {
      gamePlanId,
      termMonths: typeof slim.termMonths === "number" ? slim.termMonths : 1,
      serverName: typeof slim.serverName === "string" ? slim.serverName : undefined,
      hostname: typeof slim.hostname === "string" ? slim.hostname : undefined,
      variant: typeof slim.variant === "string" ? slim.variant : undefined,
      subdomain: typeof slim.subdomain === "string" ? slim.subdomain : undefined,
      dedicatedIp: !!slim.dedicatedIp,
      region: typeof slim.region === "string" && slim.region ? slim.region : undefined,
      provider: slim.provider === "OVH" || slim.provider === "HETZNER" ? slim.provider : undefined,
      regionSource: slim.regionSource === "geo" || slim.regionSource === "default" || slim.regionSource === "explicit" ? slim.regionSource : undefined,
      config,
    };
    return {
      kind: "gameOrder",
      userId,
      intent,
      sold: parseGameOrderPrice(md?.nxeonGameOrderPrice),
      couponReservationToken: parseId(md?.nxeonCouponReservation),
    };
  }

  const resizeRaw = md?.nxeonResize;
  if (resizeRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(resizeRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const planId = parseId(p?.planId);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || !planId || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
    }
    return { kind: "resize", userId, serverId, planId, chargeCents };
  }

  const expandRaw = md?.nxeonDiskExpand;
  if (expandRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(expandRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const addGB = parseChargeCents(p?.addGB);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || addGB === null || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
    }
    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
  }

  const dedicatedIpRaw = md?.nxeonDedicatedIp;
  if (dedicatedIpRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(dedicatedIpRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonDedicatedIp is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonDedicatedIp is missing serverId/chargeCents" };
    }
    return { kind: "dedicatedIp", userId, serverId, chargeCents };
  }

  // Shared-hosting order funded by card. The full order inputs ride in nxeonHostOrder;
  // `planId` and `idempotencyKey` are the two fields fulfilment cannot proceed without
  // (the key governs the `hostorder:<key>` placement claim), so a payload missing
  // either is `unreadable`, never a silent top-up.
  const hostRaw = md?.nxeonHostOrder;
  if (hostRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(hostRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonHostOrder is not valid JSON" };
    }
    const planId = parseId(p?.planId);
    const idempotencyKey = parseId(p?.idempotencyKey);
    if (!planId || !idempotencyKey) {
      return { kind: "unreadable", userId, detail: "nxeonHostOrder is missing planId/idempotencyKey" };
    }
    const intent: HostOrderCheckoutIntent = {
      planId,
      idempotencyKey,
      domain: typeof p.domain === "string" ? p.domain : undefined,
      subdomainLabel: typeof p.subdomainLabel === "string" ? p.subdomainLabel : undefined,
      extraDiskGB: typeof p.extraDiskGB === "number" ? p.extraDiskGB : undefined,
      termMonths: typeof p.termMonths === "number" ? p.termMonths : undefined,
      appSlug: typeof p.appSlug === "string" ? p.appSlug : undefined,
    };
    return { kind: "hostOrder", userId, intent };
  }

  // Business-email order funded by card. domainName + emailPlanId are load-bearing.
  const emailRaw = md?.nxeonEmailOrder;
  if (emailRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(emailRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonEmailOrder is not valid JSON" };
    }
    const domainName = parseId(p?.domainName);
    const emailPlanId = parseId(p?.emailPlanId);
    if (!domainName || !emailPlanId) {
      return { kind: "unreadable", userId, detail: "nxeonEmailOrder is missing domainName/emailPlanId" };
    }
    const intent: EmailOrderCheckoutIntent = {
      domainName,
      emailPlanId,
      termMonths: typeof p.termMonths === "number" ? p.termMonths : undefined,
    };
    return { kind: "emailOrder", userId, intent };
  }

  // Domain registration funded by card. `domainOrderId` is the one thing that
  // must parse — without it fulfilment has nothing to look up and this must
  // never fall through to a silent top-up. The price mirror is best-effort: a
  // bad/missing `nxeonDomainOrderPrice` still classifies as a domainOrder with
  // `sold: null`, because the DomainOrderIntent row (not this metadata) is the
  // value `placeDomainCardOrder` actually charges.
  const domainRaw = md?.nxeonDomainOrder;
  if (domainRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(domainRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is not valid JSON" };
    }
    const domainOrderId = parseId(p?.domainOrderId);
    if (!domainOrderId) {
      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is missing domainOrderId" };
    }
    let sold: DomainOrderPrice | null = null;
    const priceRaw = md?.nxeonDomainOrderPrice;
    if (priceRaw) {
      try {
        const sp = JSON.parse(priceRaw) as Record<string, unknown>;
        const priceCents = parseChargeCents(sp?.priceCents);
        const costCents = parseChargeCents(sp?.costCents);
        if (priceCents !== null && costCents !== null) sold = { priceCents, costCents };
      } catch {
        sold = null;
      }
    }
    return { kind: "domainOrder", userId, domainOrderId, sold };
  }

  return { kind: "topup", userId };
}

/**
 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
 * must never be able to mistake a transport failure for "this session is a top-up".
 */
export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
  if (!stripeConfigured()) throw new Error("Stripe is not configured");
  return stripe().checkout.sessions.retrieve(sessionId);
}

