      stripe={stripeFor(publishableKey)}
      options={{
        clientSecret,
        elementsOptions: {
          appearance: currentStripeAppearance(),
          fonts: STRIPE_FONTS,
          /* Saved cards are offered by CardForm's own chooser ("Visa •••• 4242"
