"use server";

import {
  createOrderLocalPayment,
  createGameOrderLocalPayment,
  createHostingOrderLocalPayment,
  createEmailOrderLocalPayment,
  type CreateLocalOrderPaymentResult,
} from "@/lib/actions-payment-providers";
import { isLocalOrderService } from "@/lib/local-order-payment";

/* The deploy wizard's local-payment-method entry point (PayNow, GrabPay, UPI, Alipay,
 * WeChat Pay) — ONE export dispatching to the platform's own per-product creators, exactly
 * like lib/nx/paypal-order.ts: IT TRANSLATES, IT DOES NOT DECIDE. Pricing, the wallet split,
 * promo/coupon holds, the flag/country/FX gate and the exact-amount check all live in the
 * action being called. The FormData is the wizard's REAL form, so this rail orders
 * byte-for-byte what the card path would. `expectedUsdCents` is the card leg the wizard is
 * showing; the server refuses to open a session for any other figure. */
export async function openWizardLocalPayment(
  service: string,
  method: string,
  expectedUsdCents: number,
  formData: FormData,
): Promise<CreateLocalOrderPaymentResult> {
  if (!isLocalOrderService(service)) {
    return { error: "That payment method isn't available for this product. Please pay by card or balance." };
  }
  if (service === "vps") return createOrderLocalPayment(method, expectedUsdCents, formData);
  if (service === "game") return createGameOrderLocalPayment(method, expectedUsdCents, formData);
  if (service === "hosting") {
    return createHostingOrderLocalPayment(method, expectedUsdCents, {
      planId: String(formData.get("planId") ?? ""),
      domain: String(formData.get("domain") ?? "").trim() || undefined,
      subdomainLabel: String(formData.get("subdomainLabel") ?? "").trim() || undefined,
      termMonths: Number(formData.get("termMonths") ?? 1),
      extraDiskGB: Number(formData.get("extraDiskGB") ?? 0) || undefined,
      idempotencyKey: String(formData.get("idempotencyKey") ?? ""),
      useWallet: formData.get("useWallet") !== "0",
    });
  }
  return createEmailOrderLocalPayment(method, expectedUsdCents, {
    domainName: String(formData.get("domain") ?? "").trim(),
    emailPlanId: String(formData.get("planId") ?? ""),
    termMonths: Number(formData.get("termMonths") ?? 1),
    useWallet: formData.get("useWallet") !== "0",
  });
}
