"use client";

import { useCallback, useEffect, useState } from "react";
import {
  CheckoutElementsProvider,
  useCheckoutElements,
  PaymentElement,
} from "@stripe/react-stripe-js/checkout";
import { stripeFor, currentStripeAppearance, useStripeThemeKey, STRIPE_FONTS } from "@/components/customer/PaymentStep";
import { Icon } from "./Icon";

/* The wizard's panel for a Stripe LOCAL payment method (PayNow, GrabPay, UPI, Alipay, WeChat
 * Pay). The sibling of NxCardFields, deliberately separate: that one offers saved cards and
 * confirms with a card in mind; a local session is single-method, has nothing to save, and
 * must confirm plain (`confirm({})` — never `savePaymentMethod`, which Stripe rejects for a
 * session created without it). The wizard's ONE primary button drives `confirm` exactly as it
 * does for a card, via `onConfirmReady`.
 *
 * Provider keyed on the client secret for the same reason NxCardFields is: Stripe reads it
 * once at init, so a re-prepared session must mount a fresh provider. */
export function NxLocalPayFields({
  clientSecret, publishableKey, label, onConfirmReady, onBusy,
}: {
  clientSecret: string;
  publishableKey: string;
  label: string;
  onConfirmReady: (confirm: (() => Promise<void>) | null) => void;
  onBusy: (busy: boolean, error: string | null) => void;
}) {
  const themeKey = useStripeThemeKey();
  return (
    <CheckoutElementsProvider
      key={`${themeKey}:${clientSecret}`}
      stripe={stripeFor(publishableKey)}
      options={{
        clientSecret,
        elementsOptions: { appearance: currentStripeAppearance(), fonts: STRIPE_FONTS },
      }}>
      <LocalForm label={label} onConfirmReady={onConfirmReady} onBusy={onBusy} />
    </CheckoutElementsProvider>
  );
}

/** Only valid inside <CheckoutElementsProvider>. */
function LocalForm({ label, onConfirmReady, onBusy }: {
  label: string;
  onConfirmReady: (confirm: (() => Promise<void>) | null) => void;
  onBusy: (busy: boolean, error: string | null) => void;
}) {
  const state = useCheckoutElements();
  const checkout = state.type === "success" ? state.checkout : undefined;
  const [error, setError] = useState<string | null>(null);

  const pay = useCallback(async () => {
    if (!checkout) return;
    setError(null);
    onBusy(true, null);
    try {
      const res = await checkout.confirm({});
      if (res.type === "error") {
        const msg = res.error.message ?? "That payment could not be completed. Please try again or use another method.";
        setError(msg);
        onBusy(false, msg);
        return;
      }
      /* On success Stripe sends the browser to the session's return_url
         (/api/stripe/confirm). Busy is NOT cleared, so the button cannot confirm twice. */
    } catch {
      const msg = "Something went wrong confirming your payment. Please try again.";
      setError(msg);
      onBusy(false, msg);
    }
  }, [checkout, onBusy]);

  useEffect(() => {
    onConfirmReady(checkout ? pay : null);
    return () => onConfirmReady(null);
  }, [checkout, pay, onConfirmReady]);

  if (state.type === "error") {
    return (
      <p className="rounded-[10px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.5)] px-3 py-2.5 text-[12px] text-rose">
        The payment form could not be loaded. Please try again or choose another method.
      </p>
    );
  }
  return (
    <div className="flex w-full flex-col gap-4">
      <div className="rounded-[14px] border border-[rgba(72,148,255,0.28)] bg-well p-4
                      shadow-[inset_0_1px_0_rgba(150,200,255,0.06)]">
        <div className="mb-3 flex items-center justify-between gap-3">
          <span className="flex items-center gap-2 text-[13px] font-bold text-white">
            <Icon name="lock" size={15} />Pay with {label}
          </span>
          <span className="flex items-center gap-2 text-[10.5px] font-semibold text-mint">
            <Icon name="shieldcheck" size={14} />Secure checkout
          </span>
        </div>
        <PaymentElement options={{ layout: "tabs" }} />
      </div>
      {error && (
        <p className="rounded-[10px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.5)] px-3 py-2.5 text-[12px] text-rose">
          {error}
        </p>
      )}
    </div>
  );
}
