import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { buildLocalOrderSession, isLocalOrderService, isLocalOrderSession } from "../lib/local-order-payment.ts";
import { classifyCheckoutSession } from "../lib/stripe.ts";
import { parseLocalFxRates, walletCreditCents } from "../lib/local-payment-methods.ts";

/**
 * Paying a wizard ORDER with a Stripe local method (lib/local-order-payment.ts). Pure tests:
 * amount exactness, refusals, and what the session classifies as before/after payment. The
 * DB-backed half (webhook idempotency, nothing placed before payment, flag off = none shown)
 * is test/local-order-fulfilment.test.ts.
 */

const rates = parseLocalFxRates('{"SGD":1.3,"INR":83}');
const ORDER_MD = { nxeonUserId: "u1", nxeonOrder: JSON.stringify({ planId: "p1", hostname: "h", region: "sgp1", provider: "OVH" }), nxeonOrderPrice: JSON.stringify({ chargeCents: 1299 }) };
const build = (over: Partial<Parameters<typeof buildLocalOrderSession>[0]> = {}) =>
  buildLocalOrderSession({ userId: "u1", method: "paynow", usdCents: 1299, rates, bufferPct: 2, quoteMetadata: ORDER_MD, productName: "Nxeon VPS order", ...over });

test("amount exactness: the wallet is credited EXACTLY the USD card leg, whatever the charge currency", () => {
  for (const [method, cur] of [["paynow", "SGD"], ["grabpay", "SGD"], ["upi", "INR"], ["alipay", "USD"], ["wechat_pay", "USD"]] as const) {
    for (const usd of [1, 99, 500, 1299, 4999, 123456]) {
      const b = build({ method, usdCents: usd });
      assert.ok(!("error" in b), `${method} ${usd}`);
      if ("error" in b) continue;
      assert.equal(b.currency, cur.toLowerCase());
      assert.equal(b.creditUsdCents, usd);
      assert.equal(b.metadata.nxeonCreditUsdCents, String(usd));
      // What fulfilment would credit for the session Stripe will hold.
      assert.equal(walletCreditCents({ amount_total: b.unitAmount, currency: cur, metadata: b.metadata }), usd);
      if (cur === "USD") assert.equal(b.unitAmount, usd, "USD methods charge exactly the USD figure");
      else assert.ok(b.unitAmount >= usd, "a foreign charge is never short of the USD value at rate>=1");
    }
  }
});

test("foreign-currency cents are never credited as dollars", () => {
  const b = build({ method: "upi", usdCents: 1000 });
  assert.ok(!("error" in b));
