 * (`fulfilRetrievedCheckoutSession`) — no Stripe call, no network, no real order data.
 *
 * Opt-in and fail-closed: it only runs when WIZPAY_TEST_DATABASE_URL is set AND identical to
 * DATABASE_URL AND points at 127.0.0.1 on a non-default port with a database named `wizpay`,
 * so it can never touch the shared/production database. Otherwise it is skipped.
 *
 *   initdb a scratch cluster, `DATABASE_URL=postgresql://postgres@127.0.0.1:55439/wizpay \
 *   WIZPAY_TEST_DATABASE_URL=$DATABASE_URL npx prisma db push --skip-generate`, then run this.
 *
 * What it proves about the placement path (the order itself is intentionally NOT seeded: a
 * bogus plan makes placeOrder fail AFTER the claim, which is exactly what lets us count claims):
 *  - an UNPAID local session claims nothing and credits nothing (no placement before payment);
 *  - a PAID session credits exactly the USD card leg once, however many times (or how
 *    concurrently) `completed` and `async_payment_succeeded` both arrive;
 *  - exactly one fulfilment claim exists, so exactly one placement is ever attempted;
 *  - flag off / no country / no rate => the method list is empty.
 */
const url = process.env.WIZPAY_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/wizpay$/.test(url);
const skip = safe ? false : "set WIZPAY_TEST_DATABASE_URL (throwaway 127.0.0.1 /wizpay db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let fulfil: typeof import("../lib/fulfil-checkout.ts")["fulfilRetrievedCheckoutSession"];
let enabled: typeof import("../lib/local-payments.ts")["enabledLocalMethods"];
let build: typeof import("../lib/local-order-payment.ts")["buildLocalOrderSession"];
let userId = "";

const USD = 1299;
function session(id: string, status: "paid" | "unpaid", md: Record<string, string>, charge: { total: number; currency: string }) {
  return { id, metadata: md, payment_status: status, amount_total: charge.total, currency: charge.currency, payment_intent: null, customer: null } as never;
}

before(async () => {
  if (!safe) return;
  process.env.STRIPE_SECRET_KEY = "sk_test_fake_never_called";
  db = (await import("../lib/db.ts")).db;
  fulfil = (await import("../lib/fulfil-checkout.ts")).fulfilRetrievedCheckoutSession;
  enabled = (await import("../lib/local-payments.ts")).enabledLocalMethods;
  build = (await import("../lib/local-order-payment.ts")).buildLocalOrderSession;
  const u = await db.user.create({ data: { email: `wizpay-${Date.now()}@example.test`, passwordHash: "x", name: "Wiz Pay" } });
  userId = u.id;
});
after(async () => { if (safe) await db.$disconnect(); });

async function setSettings(kv: Record<string, string>) {
  for (const [key, value] of Object.entries(kv)) await db.setting.upsert({ where: { key }, update: { value }, create: { key, value } });
}

function localSession(id: string, status: "paid" | "unpaid") {
  const body = build({
    userId, method: "paynow", usdCents: USD, rates: { USD: 1, SGD: 1.3 }, bufferPct: 2,
    quoteMetadata: { nxeonUserId: userId, nxeonOrder: JSON.stringify({ planId: "no-such-plan", hostname: "t", region: "sgp1", provider: "OVH" }), nxeonOrderPrice: JSON.stringify({ chargeCents: USD }) },
    productName: "t",
  });
  if ("error" in body) throw new Error(body.error);
  return session(id, status, body.metadata, { total: body.unitAmount, currency: "SGD" });
}

test("flag off = nothing shown; each gate (flag, entity country, FX rate) must hold", { skip }, async () => {
  assert.deepEqual(await enabled(), [], "defaults: nothing");
  await setSettings({ pay_method_paynow: "true" });
  assert.deepEqual(await enabled(), [], "flag on but no Stripe entity country");
  await setSettings({ stripe_account_country: "SG" });
  assert.deepEqual(await enabled(), [], "flag + country but no SGD rate: cannot be priced");
  await setSettings({ local_pay_fx_rates: '{"SGD":1.3}' });
  assert.deepEqual((await enabled()).map((m) => m.id), ["paynow"]);
  await setSettings({ pay_method_alipay: "true" });
  assert.deepEqual((await enabled()).map((m) => m.id), ["paynow"], "alipay not supported for an SG account");
  await setSettings({ pay_method_paynow: "false" });
  assert.deepEqual(await enabled(), [], "flag off again = nothing");
});

test("no placement before payment: an unpaid (async pending) session claims and credits nothing", { skip }, async () => {
  const r = await fulfil(localSession("cs_test_unpaid_1", "unpaid"));
  assert.equal(r.fulfilled, false);
  assert.match(r.redirect, /\/dashboard\/billing\?pending=1$/);
  assert.equal(await db.fulfilledSession.count({ where: { stripeSessionId: "cs_test_unpaid_1" } }), 0);
  assert.equal(await db.walletTransaction.count({ where: { userId } }), 0);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: userId } })).balanceCents, 0);
});

test("duplicate and concurrent webhooks: credited exactly the USD card leg once, one claim", { skip }, async () => {
  const id = "cs_test_paid_dup";
  const results = await Promise.all([fulfil(localSession(id, "paid")), fulfil(localSession(id, "paid")), fulfil(localSession(id, "paid"))]);
  // later: the second event type for the same session, and a redirect replay
  const again = await fulfil(localSession(id, "paid"));
  const all = [...results, again];
  assert.equal(await db.fulfilledSession.count({ where: { stripeSessionId: id } }), 1, "one fulfilment claim");
  assert.equal(await db.walletTransaction.count({ where: { userId, stripeSessionId: id } }), 1, "one wallet credit");
  const u = await db.user.findUniqueOrThrow({ where: { id: userId } });
  // credited exactly USD cents (1299), NOT the ~1722 SGD cents charged; the order (bogus plan) failed
  // after the claim so nothing was debited and the money is safely in the wallet.
  assert.equal(u.balanceCents, USD);
  assert.equal(all.filter((r) => r.kind === "order" && !r.fulfilled).length, all.length, "only the claim winner attempted placement; the order here fails on purpose");
  const row = await db.fulfilledSession.findUniqueOrThrow({ where: { stripeSessionId: id } });
  assert.equal(row.status, "FAILED");
});

test("a session in the wrong currency or with a tampered credit credits nothing", { skip }, async () => {
  const bad = localSession("cs_test_tamper_1", "paid") as unknown as { currency: string };
  bad.currency = "usd";
  const before = (await db.user.findUniqueOrThrow({ where: { id: userId } })).balanceCents;
  await fulfil(bad as never);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: userId } })).balanceCents, before);
  assert.equal(await db.walletTransaction.count({ where: { userId, stripeSessionId: "cs_test_tamper_1" } }), 0);
});
EOF
